import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import api from "../api/api";

const OrderConfirmation = () => {
  const { id } = useParams();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api
      .get(`/orders/${id}`)
      .then(({ data }) => setOrder(data))
      .catch(() => setOrder(null))
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <p className="text-stone text-center py-24">Loading...</p>;

  if (!order)
    return (
      <div className="text-center py-24">
        <p className="text-stone mb-4">We couldn't find that order.</p>
        <Link to="/shop" className="text-brass">Continue shopping</Link>
      </div>
    );

  return (
    <div className="max-w-2xl mx-auto px-5 py-24 text-center">
      <div className="w-16 h-16 rounded-full border border-brass flex items-center justify-center mx-auto mb-6">
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#B08D57" strokeWidth="2">
          <path d="M5 13l4 4L19 7" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </div>
      <h1 className="text-3xl text-ivory mb-3">Thank you, {order.customer.fullName}!</h1>
      <p className="text-stone mb-8">
        Your order has been placed successfully. We'll contact you at{" "}
        <span className="text-ivory">{order.customer.phone}</span> to confirm delivery details.
      </p>

      <div className="bg-charcoal border border-brass/10 p-6 text-left mb-8">
        <p className="text-sm text-stone mb-3">
          Order ID: <span className="text-ivory">{order._id}</span>
        </p>
        <div className="flex flex-col gap-2 mb-4">
          {order.items.map((item, idx) => (
            <div key={idx} className="flex justify-between text-sm">
              <span className="text-stone">
                {item.name} &times; {item.quantity}
              </span>
              <span className="text-ivory">Rs. {(item.price * item.quantity).toLocaleString()}</span>
            </div>
          ))}
        </div>
        <div className="stitch-divider mb-4" />
        <div className="flex justify-between text-ivory">
          <span>Total</span>
          <span>Rs. {order.total.toLocaleString()}</span>
        </div>
        <p className="text-xs text-stone mt-3">Payment method: {order.paymentMethod}</p>
      </div>

      <Link to="/shop" className="bg-brass text-ink px-7 py-3 text-sm">
        Continue Shopping
      </Link>
    </div>
  );
};

export default OrderConfirmation;
